lemma exp_le_quadratic_of_le {b : ℝ} (hb : 0 < b) {t : ℝ} (ht : 0 ≤ t) {x : ℝ}
    (hx : x ≤ b) :
    Real.exp (t * x) ≤ 1 + t * x + (Real.exp (t * b) - 1 - t * b) / b ^ 2 * x ^ 2

def LocalizedDeviationCertificate [Fintype Z] {n : ℕ}
    (p : Z → ℝ) (ℓ : ι → Z → ℝ) (iStar : ι)
    (z : Fin n → Z) (P : ι → Prop) (η : ℝ) : Prop

theorem localizedDeviationCertificate_of_mem_upperDeviationEvent
    [Fintype ι] [Fintype Z] {n : ℕ}
    {p : Z → ℝ} {ℓ : ι → Z → ℝ} {iStar : ι}
    {P : ι → Prop} [DecidablePred P] {hP : ∃ i : ι, P i}
    {η : ℝ} {z : Fin n → Z}
    (hz : z ∈ localizedUpperDeviationEvent p ℓ iStar P hP η) :
    LocalizedDeviationCertificate p ℓ iStar z P η

theorem finiteExcessRisk_le_of_localizedUpperDeviationEvent_empirical_nonpos
    [Fintype ι] [Fintype Z] {n : ℕ}
    {p : Z → ℝ} {ℓ : ι → Z → ℝ} {iStar i : ι}
    {P : ι → Prop} [DecidablePred P] {hP : ∃ j : ι, P j}
    {η : ℝ} {z : Fin n → Z}
    (hz : z ∈ localizedUpperDeviationEvent p ℓ iStar P hP η)
    (hi : P i)
    (hemp : empiricalExcessRisk ℓ iStar i z ≤ 0) :
    finiteExcessRisk p ℓ iStar i ≤ η

theorem finiteExcessRisk_le_of_localizedSampleDependentUpperDeviationEvent_empirical_nonpos
    [Fintype ι] [Fintype Z] {n : ℕ}
    {p : Z → ℝ} {ℓ : ι → Z → ℝ} {iStar i : ι}
    {P : ι → Prop} [DecidablePred P] {hP : ∃ j : ι, P j}
    {η : (Fin n → Z) → ℝ} {z : Fin n → Z}
    (hz : z ∈ localizedSampleDependentUpperDeviationEvent p ℓ iStar P hP η)
    (hi : P i)
    (hemp : empiricalExcessRisk ℓ iStar i z ≤ 0) :
    finiteExcessRisk p ℓ iStar i ≤ η z

theorem condExp_sq_eq_condVar_of_centered
    {Ω : Type*} {m₀ : MeasurableSpace Ω}
    {μ : Measure Ω} [IsProbabilityMeasure μ]
    {m : MeasurableSpace Ω}
    {X : Ω → ℝ}
    (_hX_meas : Measurable X)
    (_hX_sq_int : Integrable (fun ω => X ω ^ 2) μ)
    (hcenter : μ[X | m] =ᵐ[μ] 0) :
    μ[fun ω => (X ω - (μ[X | m]) ω) ^ 2 | m] =ᵐ[μ] μ[fun ω => X ω ^ 2 | m]

theorem betting_time_uniform_confidence_sequence
    {Ω : Type*} {mΩ : MeasurableSpace Ω}
    {μ : Measure Ω} [IsProbabilityMeasure μ]
    {ℱ : Filtration ℕ mΩ}
    {X lambda : ℕ → Ω → ℝ} {m delta : ℝ}
    (hdelta : 0 < delta)
    (hE : EProcess μ ℱ (bettingWealthProcess X lambda m)) :
    μ.real (bettingMeanRejectionEvent X lambda m delta) ≤ delta

theorem chernoff_tail [IsProbabilityMeasure μ] {X : Ω → ℝ} {c : ℝ≥0}
    (hSubG : HasSubgaussianMGF X c μ) {t : ℝ} (ht : 0 ≤ t) :
    μ.real {ω | t ≤ |X ω|} ≤ 2 * Real.exp (-t ^ 2 / (2 * (c : ℝ)))

theorem subGaussianMGF_tail_twoSided [IsProbabilityMeasure μ] {X : Ω → ℝ} {c : ℝ≥0}
    (hSubG : HasSubgaussianMGF (fun ω => X ω - μ[X]) c μ) {t : ℝ} (ht : 0 ≤ t) :
    μ.real {ω | t ≤ |X ω - μ[X]|} ≤ 2 * Real.exp (-t ^ 2 / (2 * (c : ℝ)))
